grid = [[7]*26 for _ in range(4)]
markers = [[3,8,9,19],[4,5,11,12,20],[6,10,13,17],[11,22]]
for r,cs in enumerate(markers):
    for c in cs: grid[r][c]=5
# fill between consecutive markers, horizontal
for r,cs in enumerate(markers):
    for a,b in zip(cs,cs[1:]):
        for c in range(a+1,b):
            if grid[r][c] != 5: grid[r][c]=3
# vertical scan
for c in range(26):
    rs=[r for r in range(4) if grid[r][c]==5]
    for a,b in zip(rs,rs[1:]):
        for r in range(a+1,b):
            if grid[r][c] != 5: grid[r][c]=3
print(grid)
print('\n'.join(' '.join(map(str,row)) for row in grid))
